insert into public.sources (id, title, publisher, url, retrieved_on, rights_note, published) values ('world-bank-pink-sheet', 'World Bank Commodity Price Data (The Pink Sheet), monthly prices', 'World Bank', 'https://www.worldbank.org/en/research/commodity-markets', '2026-11-07', 'File used: the November 2026 monthly historical workbook linked from the Commodity Markets page (CMO-Historical-Data-Monthly.xlsx). This edition copies one column, not the workbook. World Bank open-data summary terms describe a CC BY 4.0 license for Data Catalog datasets unless metadata says otherwise. This Pink Sheet file is distributed from the research page, and that CC BY statement was not confirmed for it. Site terms reviewed the same day ask for attribution and describe non-catalog materials as informational, with commercial republication requiring consent. Macro Atlas does not resell the series. For reuse, use the official workbook.', true) on conflict (id) do update set title = excluded.title, publisher = excluded.publisher, url = excluded.url, retrieved_on = excluded.retrieved_on, rights_note = excluded.rights_note, published = true;
insert into public.sources (id, title, publisher, url, retrieved_on, rights_note, published) values ('ecb-ea-10y', 'Euro area 10-year government benchmark bond yield', 'European Central Bank', 'https://data-api.ecb.europa.eu/service/data/FM/M.U2.EUR.4F.BB.U2_10Y.YLD?format=csvdata&startPeriod=2014-01', '2026-11-07', 'Retrieved from the public ECB Data Portal API. The ECB disclaimer and copyright page fetched the same day did not return a short machine-readable reproduction clause in the static HTML. This edition attributes the series to the ECB, does not imply ECB endorsement, and does not claim a resolved license for commercial redistribution. Use the ECB Data Portal for the authoritative series.', true) on conflict (id) do update set title = excluded.title, publisher = excluded.publisher, url = excluded.url, retrieved_on = excluded.retrieved_on, rights_note = excluded.rights_note, published = true;
insert into public.sources (id, title, publisher, url, retrieved_on, rights_note, published) values ('natural-earth', 'Natural Earth 1:10m land', 'Natural Earth', 'https://www.naturalearthdata.com/about/terms-of-use/', '2026-11-07', 'Natural Earth’s terms page states that the raster and vector map data on the site are in the public domain and may be used for personal, educational, and commercial purposes without permission. Attribution is not required. This edition still credits Natural Earth.', true) on conflict (id) do update set title = excluded.title, publisher = excluded.publisher, url = excluded.url, retrieved_on = excluded.retrieved_on, rights_note = excluded.rights_note, published = true;
insert into public.sources (id, title, publisher, url, retrieved_on, rights_note, published) values ('wikipedia-places', 'Wikipedia place and port articles', 'Wikimedia Foundation', 'https://en.wikipedia.org/wiki/Ras_Tanura', '2026-11-07', 'Wikipedia text is licensed CC BY-SA 4.0. This edition paraphrases short geographic descriptions and links each article. It does not copy article text in bulk. Coordinates are facts taken from those pages. Place pages are not used as sources for oil volumes or pipeline capacities.', true) on conflict (id) do update set title = excluded.title, publisher = excluded.publisher, url = excluded.url, retrieved_on = excluded.retrieved_on, rights_note = excluded.rights_note, published = true;
